Storefront Frontend (SPA).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Storefront Frontend (SPA) container

Container_Boundary(storefront_frontend_spa, "Storefront Frontend (SPA)") {
    Component(Catalog Browser Component, "Catalog Browser Component", "React, React Query", "Handles catalog browsing, searching, and product listing displays.")
    Component(Shopping Cart Component, "Shopping Cart Component", "React, RTK Query", "Manages shopping cart items, local state, and synchronization.")
    Component(Secure Checkout Component, "Secure Checkout Component", "React", "Manages the secure checkout user flow and payment UI interactions.")
    Component(Reviews and Recommendations Component, "Reviews and Recommendations Component", "React", "Displays product reviews and personalized recommendations to users.")
}

Rel(Catalog Browser Component, Shopping Cart Component, "Adds selected products", "")
Rel(Shopping Cart Component, Secure Checkout Component, "Proceeds to checkout with cart items", "")

@enduml

Edge Security & WAF.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(edge_security_waf, "Edge Security & WAF") {
    Component(Web_Application_Firewall_WAF, "Web Application Firewall (WAF)", "AWS WAF", "Protects frontend requests, mitigates attacks at the edge using AWS Managed Rules for OWASP Top 10.")
    Component(Edge_Request_Inspector, "Edge Request Inspector", "AWS CloudFront / WAF Rules", "Validates incoming traffic headers and payloads before forwarding to the API Gateway.")
}

System(API_Gateway_BFF, "API Gateway / BFF", "AWS API Gateway")

Rel(Web_Application_Firewall_WAF, Edge_Request_Inspector, "Inspects and filters requests", "")
Rel(Edge_Request_Inspector, API_Gateway_BFF, "Forwards validated traffic", "HTTPS")
@enduml

API Gateway / BFF.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_bff, "API Gateway / BFF") {
    Component(Routing_and_Rate_Limiting_Router, "Routing and Rate Limiting Router", "AWS API Gateway", "Handles native routing, request dispatching, and rate limiting to enforce the uptime SLA.")
    Component(Request_Aggregator, "Request Aggregator", "AWS Lambda / Node.js", "Aggregates responses from multiple downstream core domain services for the frontend SPA.")
}

Rel(Routing_and_Rate_Limiting_Router, Request_Aggregator, "Forwards inspected traffic")

@enduml

Core Domain Services.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Core Domain Services container

Container_Boundary(core_domain_services, "Core Domain Services") {
    Component(Order_Controller, "Order Controller", "gRPC & REST", "Handles incoming synchronous requests from the API Gateway for business logic.")
    Component(Order_Service, "Order Service", "Java / Spring Boot", "Implements domain logic for order processing, catalog browsing, and reviews.")
    Component(Event_Publisher, "Event Publisher", "AMQP / HTTPS", "Publishes asynchronous events for orders and shipping to the message broker.")
}

Rel(Order_Controller, Order_Service, "Invokes business logic")
Rel(Order_Service, Event_Publisher, "Sends asynchronous events")

@enduml

Caching Layer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Caching Layer container

Container_Boundary(caching_layer, "Caching Layer") {
    Component(Redis Cache Engine, "Redis Cache Engine", "Amazon ElastiCache (Redis)", "Handles in-memory caching using Cache-Aside pattern, volatile-lru eviction, and Redlock distributed locking with multi-AZ replication.")
    Component(Cache Invalidation Worker, "Cache Invalidation Worker", "AWS Lambda / ECS", "Listens to asynchronous messages to invalidate or refresh stale cache entries using Stale-While-Revalidate.")
}

Rel(Cache Invalidation Worker, Redis Cache Engine, "Evicts and updates keys via TCP", "TCP")

@enduml

Asynchronous Message Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Asynchronous Message Broker container

Container_Boundary(asynchronous_message_broker, "Asynchronous Message Broker") {
    Component(Event_Publisher, "Event Publisher", "AWS SNS", "Publishes domain events from core services for asynchronous processing.")
    Component(Event_Queue, "Event Queue", "AWS SQS", "Queues asynchronous tasks and events with Dead Letter Queue (DLQ) support for fault tolerance.")
}

Rel(Event_Publisher, Event_Queue, "Routes messages to appropriate queues", "AMQP/HTTPS")

@enduml
